// Normalize field names — handles various CSV export schemas
const row = $input.item.json;

const email = row.email || row.Email || row['Work Email'] || row['Email Address'] || '';

// Handle split names or full names
let name = '';
if (row.Name) {
  name = row.Name;
} else {
  const firstName = row.first_name || row['First Name'] || row.firstName || '';
  const lastName = row.last_name || row['Last Name'] || row.lastName || '';
  name = `${firstName} ${lastName}`.trim();
}

const company = row.company_name || row.Company || row['Company Name'] || row['Current Club'] || row['Target Club'] || '';
const title = row.title || row.Title || row['Job Title'] || row['Current Title'] || row['Target Title'] || '';
const linkedin = row.linkedin_url || row.LinkedIn || row['LinkedIn URL'] || row.linkedinUrl || '';
const signals = row.buying_signals || row['Buying Signals'] || row.signals || 'None detected';
const score = row.lead_score || row['Lead Score'] || row.score || 'N/A';

return [{
  json: {
    email,
    name: name || 'Unknown',
    company: company || 'Unknown Company',
    title: title || 'Unknown Title',
    linkedin,
    signals,
    score,
    run_id: `${email}-${new Date().toISOString().split('T')[0]}`
  }
}];

